Actionscript.script:
import fl.transitions.*;

// USER CONFIG SETTINGS
var buttonsOn:Boolean = true; // true, false
var pageNumberOn:Boolean = true; // true, false
var transitionOn:Boolean = true; // true, false
var transitionType:String = "Fade"; // Blinds, Fade, Fly, Iris, Photo, PixelDissolve, Rotate, Squeeze, Wipe, Zoom, Random
// END USER CONFIG SETTINGS

// EVENTS
stage.addEventListener(KeyboardEvent.KEY_DOWN, fl_changeSlideKeyboard);
prev_btn.addEventListener(MouseEvent.CLICK, fl_prevSlideButton);
next_btn.addEventListener(MouseEvent.CLICK, fl_nextSlideButton);
function fl_changeSlideKeyboard(evt:KeyboardEvent):void
{
	if(evt.keyCode == 37) // LEFT
	{
		fl_prevSlide();
	}
	else if (evt.keyCode == 39 || evt.keyCode == 32) // RIGHT OR SPACE
	{
		fl_nextSlide();
	}
}
function fl_prevSlideButton(evt:MouseEvent):void
{
	fl_prevSlide();
}
function fl_nextSlideButton(evt:MouseEvent):void
{
	fl_nextSlide();
}
// END EVENTS

// FUNCTIONS AND LOGIC
function fl_prevSlide():void
{
	if(currentFrame > 1)
	{
		gotoAndStop(currentFrame-1);
		/*if(transitionOn == true)
		{
			fl_doTransition();
		}*/
		if(pageNumberOn == false)
		{
			slideNumber_txt.text = "";
		} else {
			slideNumber_txt.text = String(currentFrame + "/" + totalFrames);
		}
	}
}
function fl_nextSlide():void
{
	if(currentFrame < totalFrames)
	{
		gotoAndStop(currentFrame+1);
		/*if(transitionOn == true)
		{
			fl_doTransition();
		}*/
		if(pageNumberOn == false)
		{
			slideNumber_txt.text = "";
		} else {
			slideNumber_txt.text = String(currentFrame + "/" + totalFrames);
		}
	}
}

gotoAndStop(1);
stage.scaleMode = StageScaleMode.SHOW_ALL;
// END FUNCTIONS AND LOGIC
stop();

/* Перемещение с помощью стрелок на клавиатуре
Разрешает перемещать указанный экземпляр символа с помощью стрелок на клавиатуре.

Инструкции:
1. Для изменения шага перемещения замените цифру 5 в коде ниже на требуемое значение одного перемещения в пикселах.
Обратите внимание, что в коде ниже цифра 5 встречается четыре раза.
*/

var upPressed:Boolean = false;
var downPressed:Boolean = false;

Java_creators.addEventListener(Event.ENTER_FRAME, fl_MoveInDirectionOfKey);
stage.addEventListener(KeyboardEvent.KEY_DOWN, fl_SetKeyPressed);
stage.addEventListener(KeyboardEvent.KEY_UP, fl_UnsetKeyPressed);

function fl_MoveInDirectionOfKey(event:Event)
{
	if (upPressed)
	{
		Java_creators.y -= 5;
	}
	if (downPressed)
	{
		Java_creators.y += 5;
	}
}

function fl_SetKeyPressed(event:KeyboardEvent):void
{
	switch (event.keyCode)
	{
		case Keyboard.UP:
		{
			upPressed = true;
			break;
		}
		case Keyboard.DOWN:
		{
			downPressed = true;
			break;
		}
	}
}

function fl_UnsetKeyPressed(event:KeyboardEvent):void
{
	switch (event.keyCode)
	{
		case Keyboard.UP:
		{
			upPressed = false;
			break;
		}
		case Keyboard.DOWN:
		{
			downPressed = false;
			break;
		}
	}
}
